import math

def P(n):
    # Polynomial from W2, round 1, which was tested by W4, round 2
    # P(x) = x^3 - 4049x^2 + 4098600x + 1
    return n**3 - 4049 * n**2 + 4098600 * n + 1

def is_perfect_square(k):
    if k < 0:
        return False
    if k == 0:
        return True
    root = math.isqrt(k)
    return root * root == k

solutions = []
# Search range: |n| < 1000, so n from -999 to 999
for n in range(-999, 1000):
    value = P(n)
    if is_perfect_square(value):
        solutions.append(n)

print(f"Solutions found in the range |n| < 1000 for P(x) = x^3 - 4049x^2 + 4098600x + 1:")
print(solutions)

